contactos = {"Ana": "555-1234", "Luis": "555-9876"}

def buscar(nombre):
    return contactos.get(nombre, "No encontrado")

print(buscar("Ana"))
print(buscar("Marta"))

def promedio(examen, proyecto, practicas):
    return examen * 0.3 + proyecto * 0.3 + practicas * 0.4

def estado(nota_final):
    if nota_final >= 5:
        return "aprobado"
    return "reprobado"

nota = promedio(8, 7, 9)
print(estado(nota))
